namespace OCA\AustitUpdates\Service;

/**
 * Reads the manifest of files that differ from upstream Nextcloud.
 * The manifest is generated by austit-dev/generate-update-manifest.php.
 *
 * @psalm-type ManifestFile = array{path: string, kind: 'modified'|'deleted'|'theme-override', sha256: string, source?: string}
 * @psalm-type Manifest = array{baseVersion: string, upstreamTag: string, generatedAt: string, files: list<ManifestFile>}
 */
class ManifestReader {
	public const KINDS = ['modified', 'deleted', 'theme-override'];

	public function getDefaultPath(): string {
		return dirname(__DIR__, 2) . '/update-manifest.json';
	}

	/**
	 * @return Manifest
	 * @throws \RuntimeException
	 */
	public function read(?string $path = null): array {
		$path ??= $this->getDefaultPath();
		if (!is_file($path)) {
			throw new \RuntimeException('Update-Manifest fehlt. Bitte austit-dev/generate-update-manifest.php ausführen.');
		}
		$data = json_decode((string)file_get_contents($path), true);
		if (!is_array($data)
			|| !is_string($data['baseVersion'] ?? null)
			|| !is_string($data['upstreamTag'] ?? null)
			|| !is_array($data['files'] ?? null)) {
			throw new \RuntimeException('Update-Manifest ist ungültig.');
		}

		$files = [];
		foreach ($data['files'] as $file) {
			if (!is_array($file)
				|| !is_string($file['path'] ?? null)
				|| !is_string($file['sha256'] ?? null)
				|| !in_array($file['kind'] ?? null, self::KINDS, true)) {
				throw new \RuntimeException('Update-Manifest enthält einen ungültigen Eintrag.');
			}
			$entry = ['path' => $file['path'], 'kind' => $file['kind'], 'sha256' => $file['sha256']];
			if (is_string($file['source'] ?? null)) {
				$entry['source'] = $file['source'];
			}
			$files[] = $entry;
		}

		return [
			'baseVersion' => $data['baseVersion'],
			'upstreamTag' => $data['upstreamTag'],
			'generatedAt' => (string)($data['generatedAt'] ?? ''),
			'files' => $files,
		];
	}
}
